import {api,escapeHtml as esc} from './catalog.js';
export const kindNames={image:'Hình ảnh',video:'Video',audio:'Audio tiếng Việt',document:'PDF / DOCX',text:'Văn bản'};
export const adminNav='<nav class="admin-subnav" aria-label="Quản trị"><a href="/quan-ly/">Tác phẩm</a><a href="/tai-nguyen/quan-ly/">Kho tài nguyên</a><a href="/nguoi-dung/">Người dùng</a><a href="/thong-ke/">Thống kê</a></nav>';
export const bytes=n=>Number(n||0)<1048576?(Number(n||0)/1024).toFixed(1)+' KiB':(Number(n||0)/1048576).toFixed(2)+' MiB';
export function visitor(){try{let id=localStorage.getItem('net.visitor');if(!id){id=crypto.randomUUID();localStorage.setItem('net.visitor',id);}return id;}catch{return 'session';}}
export const fileURL=(r,download=false)=>'/api/resources/'+encodeURIComponent(r.id)+'/file'+(download?'?download=1&visitor='+visitor():'');
export function resourceCard(r){return `<article class="resource-card"><a class="resource-thumb" href="/tai-nguyen/?id=${encodeURIComponent(r.id)}">${r.resourceType==='image'?`<img src="${esc(r.url)}" alt="${esc(r.title)}" loading="lazy">`:`<span>${esc(kindNames[r.resourceType]||r.resourceType)}</span>`}</a><div class="resource-copy"><span class="type-badge">${esc(r.format?.toUpperCase()||kindNames[r.resourceType])} · ${bytes(r.sizeBytes)}</span><h3><a href="/tai-nguyen/?id=${encodeURIComponent(r.id)}">${esc(r.title||r.originalName||'Tư liệu')}</a></h3><p>${esc(r.author||'Nét — bảo tàng số')}</p>${r.similarity!==undefined?`<p class="score-note">Tương đồng màu: ${(r.similarity*100).toFixed(1)}%</p>`:''}</div></article>`;}
export function trackView(id){api('/resources/'+encodeURIComponent(id)+'/events?visitor='+visitor(),{method:'POST',body:JSON.stringify({action:'view'})}).catch(()=>{});}
export function player(r){const url=esc(fileURL(r));if(r.resourceType==='image')return `<img src="${url}" alt="${esc(r.title)}">`;if(['audio','video'].includes(r.resourceType))return `<${r.resourceType} controls preload="metadata" ${r.resourceType==='video'?`playsinline ${r.poster?'poster="'+esc(r.poster)+'"':''}`:''} src="${url}" aria-label="${esc(r.title)}"></${r.resourceType}>${r.resourceType==='audio'?'<p class="subtle-note">Thuyết minh tiếng Việt · giọng đọc tổng hợp trong tư liệu mẫu.</p>':''}${r.transcript?`<details><summary>Nội dung thuyết minh</summary><p>${esc(r.transcript)}</p></details>`:''}`;if(r.format?.toLowerCase()==='pdf')return `<iframe src="${url}" title="${esc(r.title)}"></iframe>`;return `<pre>${esc(r.content||'Tải tệp để đọc toàn bộ nội dung.')}</pre>`;}
export function bindPlayer(container,r){if(['audio','video'].includes(r.resourceType))container.querySelector(r.resourceType)?.addEventListener('play',()=>trackView(r.id),{once:true});else trackView(r.id);}
export async function renderResource(){const target=document.querySelector('#resource-view');try{const {resource:r}=await api('/resources/'+encodeURIComponent(new URLSearchParams(location.search).get('id')||''));document.title=r.title+' · Nét';target.innerHTML=`<div class="resource-view-header"><div><span class="eyebrow">${esc(kindNames[r.resourceType])}</span><h2>${esc(r.title)}</h2><p>${esc(r.author)}</p></div><a class="button button-dark" href="${esc(fileURL(r,true))}">Tải tư liệu ↓</a></div><div class="resource-player">${player(r)}</div><p>${esc(r.description)}</p><dl class="resource-metadata"><div><dt>Mã tư liệu</dt><dd>${esc(r.id)}</dd></div><div><dt>Vị trí lưu trữ</dt><dd>${esc(r.url)}</dd></div><div><dt>Dung lượng</dt><dd>${bytes(r.sizeBytes)}</dd></div><div><dt>Định dạng</dt><dd>${esc(r.mimeType)}</dd></div><div><dt>Ngày thêm</dt><dd>${new Date(r.createdAt).toLocaleDateString('vi-VN')}</dd></div>${r.duration?`<div><dt>Thời lượng</dt><dd>${Number(r.duration).toFixed(1)} giây</dd></div>`:''}${r.width?`<div><dt>Kích thước</dt><dd>${r.width} × ${r.height} px</dd></div>`:''}${r.pageCount?`<div><dt>Số trang</dt><dd>${r.pageCount}</dd></div>`:''}<div><dt>Chủ đề</dt><dd>${esc(r.topics?.join(', '))||'—'}</dd></div><div><dt>Từ khóa</dt><dd>${esc(r.tags?.join(', '))||'—'}</dd></div><div><dt>Bản quyền</dt><dd>${esc(r.license)||'Chưa cung cấp'}</dd></div><div><dt>Nguồn</dt><dd>${r.source?`<a href="${esc(r.source)}" rel="noopener noreferrer" target="_blank">Xem nguồn ↗</a>`:'—'}</dd></div></dl>${r.resourceType==='image'?`<a class="button button-outline" href="/tim-kiem/?similar=${encodeURIComponent(r.id)}">Tìm ảnh tương tự ↗</a>`:''}<div class="attachment-gallery">${(r.artworks||[]).map(a=>`<a href="/tac-pham/?id=${encodeURIComponent(a.id)}">Hồ sơ: ${esc(a.title)} ↗</a>`).join('')}</div>`;bindPlayer(target,r);}catch(error){target.textContent=error.message;}}
export async function enhanceArtwork(id){const layout=document.querySelector('.detail-layout');if(!layout)return;try{const {items}=await api('/artworks/'+encodeURIComponent(id)+'/resources');if(document.querySelector('.artwork-media-section'))return;const images=items.filter(r=>r.resourceType==='image'),rest=items.filter(r=>r.resourceType!=='image');rest.forEach(r=>{r.poster=images[0]?.url;});layout.querySelector('.artwork-video')?.remove();const section=document.createElement('section');section.className='artwork-media-section wrap';section.innerHTML=`<h2>Ngắm, nghe và đọc.</h2><p>Những góc nhìn và tư liệu đi cùng tác phẩm.</p><div class="attachment-gallery">${images.map(r=>`<button class="button button-outline" data-image-id="${esc(r.id)}">${esc(r.purpose==='cover'?'Ảnh chính':r.title||'Ảnh chi tiết')}</button>`).join('')}</div><div class="media-pair">${rest.filter(r=>['audio','video'].includes(r.resourceType)).map(r=>`<article data-player-id="${esc(r.id)}"><h3>${esc(r.title)}</h3><div class="resource-player">${player(r)}</div><a href="${esc(fileURL(r,true))}">Tải ${esc(kindNames[r.resourceType])} ↓</a></article>`).join('')}</div><div class="resource-grid">${rest.filter(r=>!['audio','video'].includes(r.resourceType)).map(resourceCard).join('')}</div><p><a href="/tim-kiem/?similar=${encodeURIComponent(images[0]?.id||'')}">Tìm ảnh có màu sắc tương tự ↗</a></p>`;layout.after(section);section.querySelectorAll('[data-image-id]').forEach(button=>button.addEventListener('click',()=>{const r=images.find(r=>r.id===button.dataset.imageId);const image=document.querySelector('#detail-image');if(image){image.src=r.url;image.alt=r.title;}trackView(r.id);}));rest.filter(r=>['audio','video'].includes(r.resourceType)).forEach(r=>bindPlayer(section.querySelector(`[data-player-id="${r.id}"]`),r));if(images[0])trackView(images[0].id);}catch(error){console.warn('Không mở được tư liệu:',error.message);}}
export async function renderStatistics(target){try{const s=await api('/stats');target.innerHTML=`<div class="feature-intro"><h2>Bảo tàng qua những con số.</h2><p>${s.totals.artworks} tác phẩm · ${s.totals.resources} tài nguyên · ${bytes(s.totals.bytes)}</p></div><div class="stats-kind-grid">${s.byKind.map(k=>`<article><p>${kindNames[k.kind]}</p><strong>${k.count}</strong><p>${bytes(k.bytes)}</p></article>`).join('')}</div><h3>Hiện vật được quan tâm</h3><ol class="stats-rank">${s.topArtworks.map(a=>`<li><a href="/tac-pham/?id=${encodeURIComponent(a.id)}">${esc(a.title)}</a><strong>${a.count}</strong></li>`).join('')||'<li>Chưa ghi nhận lượt xem.</li>'}</ol><h3>Tài nguyên theo chủ đề</h3><div class="table-scroll"><table class="feature-table"><thead><tr><th>Chủ đề</th><th>Tư liệu</th><th>Lượt xem</th><th>Lượt tải</th></tr></thead><tbody>${s.byTopic.map(t=>`<tr><td>${esc(t.name)}</td><td>${t.resources}</td><td>${t.views}</td><td>${t.downloads}</td></tr>`).join('')}</tbody></table></div><div class="media-pair">${[['Xem nhiều nhất',s.topViewed],['Tải nhiều nhất',s.topDownloaded]].map(([label,rows])=>`<section><h3>${label}</h3><ol class="stats-rank">${rows.map(r=>`<li><a href="/tai-nguyen/?id=${encodeURIComponent(r.id)}">${esc(r.title)}</a><strong>${r.count}</strong></li>`).join('')||'<li>Chưa ghi nhận lượt tương tác.</li>'}</ol></section>`).join('')}</div><p class="subtle-note">Số liệu lưu tập trung trong PostgreSQL. Mỗi trình duyệt, mỗi tư liệu và mỗi hành động được ghi một lần trong một giờ. Lượt tải tính theo yêu cầu tải tệp; không xác nhận người dùng đã tải xong. Một tư liệu có thể thuộc nhiều chủ đề.</p>`;}catch(error){target.textContent=error.message;}}
